"""Replace generic Python variants with curated questions for a review batch."""
import csv
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
PATH=ROOT/'docs/python-questions-additional.csv'
CURATED={
'fundamentals':{
1:["Какво се случва при `x = 10; y = x` и после `x = 20`? Обясни кои имена и обекти са свързани.","Каква е ролята на отстъпите в Python и какво ще стане при смесване на tab и spaces?","Кога блокът `if __name__ == '__main__':` се изпълнява и защо е полезен?","Как се различават синтактична грешка, runtime exception и логическа грешка?"],
2:["Функция приема списък и го променя. Как ще покажеш разликата между промяна на обекта и повторно присвояване на локално име?","Как ще разделиш CLI входа от чистата логика така че модулът да може да се импортира без страничен ефект?","Как ще използваш type hints и `dataclass` за малък обект с две задължителни полета?","Кога ще хвърлиш собствено изключение вместо да върнеш `None`?"],
3:["Модул изпълнява заявка към база още при import. Как ще откриеш причината и ще преместиш страничния ефект в явна функция?","Функция има mutable default аргумент. Покажи защо извикванията споделят състояние и как ще го поправиш.","Как ще обработиш exception така че да добавиш контекст, без да изгубиш traceback-а?","Два модула имат цикличен import. Как ще промениш зависимостите без да скриеш архитектурния проблем?"],
4:["Проектираш пакет с публичен API и вътрешни модули. Как ще контролираш export-ите, зависимостите и обратната съвместимост?","Как ще организираш конфигурация, логиране и dependency injection в Python услуга, за да се тества без реална инфраструктура?","Сравни context manager, try/finally и декоратор за гарантирано освобождаване на ресурс.","Как ще мигрираш голям модул със скрити странични ефекти към чисти функции без да счупиш потребителите му?"],
5:["Голяма услуга има различно поведение според import order и среда. Как ще разделиш initialization, конфигурация и публичен API?","След deployment расте паметта заради обекти задържани от глобално състояние. Как ще докажеш причината и ще въведеш безопасна промяна?","Как ще проектираш backward-compatible миграция на пакет когато няколко приложения използват различни версии едновременно?","Как ще създадеш recovery и observability план за критична Python библиотека която се използва от много услуги?"]},
'language_basics':{
1:["Кои от `None`, `0`, `''`, `[]` и `False` са falsy и защо `is None` е по-точно от `== None`?","Каква е разликата между `==` и `is` в Python? Дай пример с малки immutable стойности и отделни списъци.","Как работят `and` и `or` като връщат операнд, а не непременно bool?","Какво е разопаковане при `a, b = pair` и какво става ако броят на стойностите не съвпадне?"],
2:["Функция трябва да различава липсващ аргумент от изрично подаден `None`. Какъв sentinel ще използваш?","Как ще обясниш разликата между `for` и `while` и как ще предотвратиш безкраен цикъл?","Как ще обработиш `ValueError` при преобразуване на вход от потребител, без да скриеш други грешки?","Как ще използваш f-string безопасно при форматиране на стойности с фиксиран брой знаци?"],
3:["Изразът `value or fallback` заменя валидната стойност `0`. Как ще го поправиш и какви гранични случаи ще тестваш?","Имаш вложени `if` проверки за три състояния. Как ще ги пренапишеш така че да няма неволно пропуснат клон?","Функция променя списък докато го обхожда. Какъв дефект може да възникне и как ще го избегнеш?","`try` блок обхваща твърде много код и скрива програмна грешка. Как ще ограничиш обработката?"],
4:["Как ще проектираш публична функция с ясни preconditions, postconditions и типове така че грешните входове да се отхвърлят рано?","Сравни `match` pattern matching с поредица от `if/elif` за обработка на структурирани входове.","Как ще направиш преобразуване на конфигурация идемпотентно и проверимо при частично невалиден вход?","Как ще мигрираш код който разчита на implicit truthiness към явни проверки без промяна на бизнес семантиката?"],
5:["Промяна в input validation трябва да се пусне към много клиенти с различни очаквания. Как ще въведеш версия и постепенно затягане на договора?","Система приема malformed входове и понякога записва частично състояние. Как ще проектираш atomic validation и rollback?","Как ще разследваш рядък production bug причинен от комбинация от типове, encoding и implicit conversions?","Как ще определиш кои runtime проверки са критични за сигурност и кои могат да останат type-checking правила?"]}}

def main():
    rows=list(csv.DictReader(PATH.open(encoding='utf-8-sig',newline='')))
    kept=[r for r in rows if r['subtopic_slug'] not in CURATED]
    for slug,levels in CURATED.items():
        for difficulty,texts in levels.items():
            for text in texts: kept.append({'subtopic_slug':slug,'difficulty':str(difficulty),'text':text})
    with PATH.open('w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['subtopic_slug','difficulty','text']); w.writeheader(); w.writerows(kept)
    print(f'Replaced curated variants for {len(CURATED)} Python subtopics')
if __name__=='__main__': main()
